   116	        }
   117	        currentOwner.setAddress(ownerFieldsDto.getAddress());
   118	        currentOwner.setCity(ownerFieldsDto.getCity());
   119	        currentOwner.setFirstName(ownerFieldsDto.getFirstName());
   120	        currentOwner.setLastName(ownerFieldsDto.getLastName());
   121	        currentOwner.setTelephone(ownerFieldsDto.getTelephone());
   122	        this.clinicService.saveOwner(currentOwner);
   123	        return new ResponseEntity<>(ownerMapper.toOwnerDto(currentOwner), HttpStatus.NO_CONTENT);
   124	    }
