   126	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
   127	    @Transactional
   128	    @Override
   129	    public ResponseEntity<OwnerDto> deleteOwner(Integer ownerId) {
   130	        Owner owner = this.clinicService.findOwnerById(ownerId);
   131	        if (owner == null) {
   132	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
   133	        }
   134	        // Soft-delete: flag the owner deleted and retain the row rather than removing it, so it
   135	        // is still readable via GET while being ignored by the create duplicate/identity checks.
   136	        owner.setDeleted(true);
   137	        this.clinicService.saveOwner(owner);
   138	        return new ResponseEntity<>(HttpStatus.NO_CONTENT);
   139	    }
