    24	import org.slf4j.Logger;
    25	import org.slf4j.LoggerFactory;
    26	import org.springframework.http.HttpHeaders;
    27	import org.springframework.http.HttpStatus;
    28	import org.springframework.http.ResponseEntity;
    29	import org.springframework.samples.petclinic.mapper.OwnerMapper;
    30	import org.springframework.samples.petclinic.model.Owner;
    31	import org.springframework.samples.petclinic.rest.dto.OwnerDto;
    32	import org.springframework.samples.petclinic.rest.dto.OwnerFieldsDto;
    33	import org.springframework.samples.petclinic.service.ClinicService;
    34	import org.springframework.samples.petclinic.util.HashUtils;
    35	import org.springframework.samples.petclinic.util.IdentityUtils;
    36	import org.springframework.stereotype.Component;
    37	import org.springframework.web.util.UriComponentsBuilder;
    38	
    39	/**
    40	 * Owns the owner-creation concern: the single place that turns a submitted
    41	 * {@link OwnerFieldsDto} into a validated, normalized, enriched and persisted {@link Owner},
    42	 * and reports the create outcome as the HTTP response the endpoint returns.
    43	 *
    44	 * <p>Keeping the whole create pipeline here means every rule that fires on create — the
    45	 * registration-date and business-day handling, the per-day and per-city quotas, the
    46	 * address/telephone/email/postcode normalization and validation, the household, duplicate
    47	 * and soft-match identity rules, and the derived customer code, namesake count and
    48	 * membership number — reads the one owner this class builds, in the one order it applies
    49	 * them, so they can never drift apart. The controller is left holding only the endpoint's
    50	 * HTTP boundary.
    51	 */
    52	@Component
    53	public class OwnerRegistrar {
    54	
    55	    /** Minimal syntactic check for an email address: a non-empty local part, a single
    56	     *  '@', and a dotted domain, none containing whitespace or a second '@'. */
    57	    private static final Pattern EMAIL_PATTERN =
    58	        Pattern.compile("^[^@\\s]+@[^@\\s]+\\.[^@\\s]+$");
    59	
    60	    /** A postcode, when supplied, must be exactly four digits before its region range is checked. */
    61	    private static final Pattern POSTCODE_PATTERN = Pattern.compile("^[0-9]{4}$");
    62	
    63	    /** Disposable email domains that are rejected: an owner whose email domain matches one of
    64	     *  these (case-insensitively) is refused with 400. */
    65	    private static final java.util.Set<String> DISPOSABLE_EMAIL_DOMAINS =
    66	        java.util.Set.of("mailinator.com", "tempmail.com", "guerrillamail.com");
    67	
    68	    /** Dedicated audit logger; emits an audit line on successful owner create. */
    69	    private static final Logger AUDIT = LoggerFactory.getLogger("AUDIT");
    70	
    71	    private final ClinicService clinicService;
    72	
    73	    private final OwnerMapper ownerMapper;
    74	
    75	    private final TelephoneNormalizer telephoneNormalizer;
    76	
    77	    private final AddressNormalizer addressNormalizer;
    78	
    79	    private final CityRegionResolver cityRegionResolver;
    80	
    81	    private final HouseholdResolver householdResolver;
    82	
    83	    public OwnerRegistrar(ClinicService clinicService,
    84	                          OwnerMapper ownerMapper,
    85	                          TelephoneNormalizer telephoneNormalizer,
    86	                          AddressNormalizer addressNormalizer,
    87	                          CityRegionResolver cityRegionResolver,
    88	                          HouseholdResolver householdResolver) {
    89	        this.clinicService = clinicService;
    90	        this.ownerMapper = ownerMapper;
    91	        this.telephoneNormalizer = telephoneNormalizer;
    92	        this.addressNormalizer = addressNormalizer;
    93	        this.cityRegionResolver = cityRegionResolver;
    94	        this.householdResolver = householdResolver;
    95	    }
    96	
    97	    /**
    98	     * Validate, normalize, enrich and persist a new owner from the submitted fields, and
    99	     * report the outcome as the response the create endpoint returns: {@code 201 Created}
   100	     * (with a {@code Location} header and the created owner) on success, or the appropriate
   101	     * rejection status ({@code 400}, {@code 409} or {@code 429}) when a create rule refuses
   102	     * the request. No owner is persisted unless every rule passes.
   103	     *
   104	     * @param ownerFieldsDto the submitted owner fields
   105	     * @return the create outcome as an HTTP response
   106	     */
   107	    public ResponseEntity<OwnerDto> register(OwnerFieldsDto ownerFieldsDto) {
   108	        HttpHeaders headers = new HttpHeaders();
   109	        Owner owner = ownerMapper.toOwner(ownerFieldsDto);
   110	        if (owner.getRegistrationDate() == null) {
   111	            owner.setRegistrationDate(LocalDate.now());
   112	        }
   113	        // A supplied registration date may not be later than the server's current date.
   114	        if (owner.getRegistrationDate().isAfter(LocalDate.now())) {
   115	            return new ResponseEntity<>(HttpStatus.BAD_REQUEST);
   116	        }
   117	        owner.setRegistrationDate(toBusinessDay(owner.getRegistrationDate()));
   118	        LocalDate registrationDate = owner.getRegistrationDate();
   119	        long ownersCreatedThatDay = this.clinicService.findAllOwners().stream()
   120	            .map(Owner::getRegistrationDate)
   121	            .filter(registrationDate::equals)
   122	            .count();
   123	        if (ownersCreatedThatDay >= 100) {
   124	            return new ResponseEntity<>(HttpStatus.TOO_MANY_REQUESTS);
   125	        }
   126	        String address = normalizedAddress(owner);
   127	        if (address == null) {
   128	            return new ResponseEntity<>(HttpStatus.BAD_REQUEST);
   129	        }
   130	        owner.setAddress(address);
   131	        String telephone = telephoneNormalizer.normalize(owner.getTelephone());
   132	        if (telephone == null) {
   133	            return new ResponseEntity<>(HttpStatus.BAD_REQUEST);
   134	        }
   135	        if (!telephoneNormalizer.hasValidNationalNumberLength(telephone)) {
   136	            return new ResponseEntity<>(HttpStatus.BAD_REQUEST);
   137	        }
   138	        owner.setTelephone(telephone);
   139	        String email = owner.getEmail();
   140	        if (email != null) {
   141	            email = email.trim();
   142	            if (!EMAIL_PATTERN.matcher(email).matches()) {
   143	                return new ResponseEntity<>(HttpStatus.BAD_REQUEST);
   144	            }
   145	            String domain = email.substring(email.indexOf('@') + 1).toLowerCase(Locale.ROOT);
   146	            if (DISPOSABLE_EMAIL_DOMAINS.contains(domain)) {
   147	                return new ResponseEntity<>(HttpStatus.BAD_REQUEST);
   148	            }
   149	            owner.setEmail(email.toLowerCase(Locale.ROOT));
   150	        }
   151	        // A postcode is optional, but when supplied it must be four digits and valid for the
   152	        // owner's city per the fixed region table; a city with no known region accepts any
   153	        // 4-digit postcode. Reject an out-of-range or malformed postcode with 400.
   154	        String postcode = owner.getPostcode();
   155	        if (postcode != null) {
   156	            if (!POSTCODE_PATTERN.matcher(postcode).matches()
   157	                    || !cityRegionResolver.isPostcodeValidForCity(owner.getCity(), postcode)) {
   158	                return new ResponseEntity<>(HttpStatus.BAD_REQUEST);
   159	            }
   160	        }
   161	        // The owner's telephone and email are now in their canonical, stored form.
   162	        // The household id is deterministic: owners with the same normalized last name and
   163	        // postcode share it automatically. Assign it unconditionally before the duplicate
   164	        // checks so both the household-duplicate rule and the identity-key rule key off the
   165	        // same computed id.
   166	        owner.setHouseholdId(householdResolver.householdId(owner));
   167	        boolean sharesHousehold = Boolean.TRUE.equals(ownerFieldsDto.getSharesHousehold());
   168	        boolean householdMember = householdResolver.householdExists(owner);
   169	        // Because the household is keyed on (lastName, postcode), a second owner sharing an
   170	        // existing owner's household is a household duplicate and is rejected with 409. The
   171	        // 'sharesHousehold' flag only bypasses this block, declaring a deliberate member; it
   172	        // no longer creates the link, which the deterministic id now does on its own.
   173	        if (householdMember && !sharesHousehold) {
   174	            return new ResponseEntity<>(HttpStatus.CONFLICT);
   175	        }
   176	        if (isDuplicateOwner(owner)) {
   177	            return new ResponseEntity<>(HttpStatus.CONFLICT);
   178	        }
   179	        String cityKey = IdentityUtils.normalizeIdentity(owner.getCity());
   180	        long ownersInCity = this.clinicService.findAllOwners().stream()
   181	            .filter(existing -> IdentityUtils.normalizeIdentity(existing.getCity()).equals(cityKey))
   182	            .count();
   183	        if (ownersInCity >= 50) {
   184	            return new ResponseEntity<>(HttpStatus.CONFLICT);
   185	        }
   186	        owner.setCustomerCode(customerCode(owner));
   187	        owner.setNamesakeCount(namesakeCount(owner));
   188	        owner.setMembershipNumber(membershipNumber(owner.getCustomerCode(), owner.getRegistrationDate()));
   189	        owner.setBulkSignupWarning(ownersCreatedThatDay > 80);
   190	        // Soft-match: the candidate has already cleared the hard-duplicate check, but it may
   191	        // still share an existing owner's last name and postcode while carrying a different
   192	        // telephone. When it does, it is created but flagged as a possible duplicate of that
   193	        // existing owner; otherwise the flag is false and no reference is recorded. A declared
   194	        // household member (created via 'sharesHousehold') is not a suspected duplicate, so it
   195	        // is never flagged.
   196	        Integer possibleDuplicateOf = (sharesHousehold && householdMember) ? null : possibleDuplicateOf(owner);
   197	        owner.setPossibleDuplicate(possibleDuplicateOf != null);
   198	        owner.setPossibleDuplicateOf(possibleDuplicateOf);
   199	        this.clinicService.saveOwner(owner);
   200	        AUDIT.info("owner created id={} customerCode={} registrationDate={} membershipLevel={} membershipNumber={}",
   201	            owner.getId(), owner.getCustomerCode(), owner.getRegistrationDate(),
   202	            ownerMapper.membershipLevel(owner), owner.getMembershipNumber());
   203	        OwnerDto ownerDto = ownerMapper.toOwnerDto(owner);
   204	        headers.setLocation(UriComponentsBuilder.newInstance()
   205	            .path("/api/owners/{id}").buildAndExpand(owner.getId()).toUri());
   206	        return new ResponseEntity<>(ownerDto, headers, HttpStatus.CREATED);
   207	    }
   208	
   209	    /**
   210	     * The owner's postal address in the single canonical form under which it is stored, or
   211	     * {@code null} when the owner supplies no usable address. An owner may supply its address
   212	     * in EITHER form: the structured {@code addressLine1} (with an optional {@code addressLine2})
   213	     * is preferred, and the flat {@code address} remains accepted for backward compatibility.
   214	     *
   215	     * <p>Normalization by {@link AddressNormalizer} is applied to whichever fields are supplied.
   216	     * When a non-blank {@code addressLine1} is present the owner's structured fields are replaced
   217	     * with their normalized values (a blank or absent {@code addressLine2} is cleared to
   218	     * {@code null}) and the returned address is composed as the normalized {@code addressLine1},
   219	     * with a single space and the normalized {@code addressLine2} appended when present. Otherwise
   220	     * the flat {@code address} is normalized and the structured fields are cleared. A blank result
   221	     * (no usable address in either form) has no canonical form and is reported as {@code null} so
   222	     * the caller can reject the request with 400.
   223	     *
   224	     * <p>This is the single point at which an owner's address is resolved and normalized on
   225	     * create, so every rule keyed on the stored address reads the one value produced here.
   226	     *
   227	     * @param owner the owner about to be created
   228	     * @return the canonical stored address, or {@code null} when the owner supplies none
   229	     */
   230	    private String normalizedAddress(Owner owner) {
   231	        String rawLine1 = owner.getAddressLine1();
   232	        if (rawLine1 != null && !rawLine1.isBlank()) {
   233	            String line1 = addressNormalizer.normalize(rawLine1);
   234	            String line2 = addressNormalizer.normalize(owner.getAddressLine2());
   235	            owner.setAddressLine1(line1);
   236	            owner.setAddressLine2(line2.isBlank() ? null : line2);
   237	            return line2.isBlank() ? line1 : line1 + " " + line2;
   238	        }
   239	        owner.setAddressLine1(null);
   240	        owner.setAddressLine2(null);
   241	        String address = addressNormalizer.normalize(owner.getAddress());
   242	        return address.isBlank() ? null : address;
   243	    }
   244	
   245	    /**
