413	   164	        // checks so both the household-duplicate rule and the identity-key rule key off the
414	   165	        // same computed id.
415	   166	        owner.setHouseholdId(householdResolver.householdId(owner));
416	   167	        boolean sharesHousehold = Boolean.TRUE.equals(ownerFieldsDto.getSharesHousehold());
417	   168	        boolean householdMember = householdResolver.householdExists(owner);
418	   169	        // Because the household is keyed on (lastName, postcode), a second owner sharing an
419	   170	        // existing owner's household is a household duplicate and is rejected with 409. The
420	   171	        // 'sharesHousehold' flag only bypasses this block, declaring a deliberate member; it
421	   172	        // no longer creates the link, which the deterministic id now does on its own.
422	   173	        if (householdMember && !sharesHousehold) {
423	   174	            return new ResponseEntity<>(HttpStatus.CONFLICT);
424	   175	        }
425	   176	        if (isDuplicateOwner(owner)) {
426	   177	            return new ResponseEntity<>(HttpStatus.CONFLICT);
427	   178	        }
428	   179	        String cityKey = IdentityUtils.normalizeIdentity(owner.getCity());
429	   180	        long ownersInCity = this.clinicService.findAllOwners().stream()
430	   181	            .filter(existing -> IdentityUtils.normalizeIdentity(existing.getCity()).equals(cityKey))
431	   182	            .count();
432	   183	        if (ownersInCity >= 50) {
433	   184	            return new ResponseEntity<>(HttpStatus.CONFLICT);
434	   185	        }
435	   186	        owner.setCustomerCode(customerCode(owner));
436	   187	        owner.setNamesakeCount(namesakeCount(owner));
437	   188	        owner.setMembershipNumber(membershipNumber(owner.getCustomerCode(), owner.getRegistrationDate()));
438	   189	        owner.setBulkSignupWarning(ownersCreatedThatDay > 80);
439	   190	        // Soft-match: the candidate has already cleared the hard-duplicate check, but it may
440	   191	        // still share an existing owner's last name and postcode while carrying a different
441	   192	        // telephone. When it does, it is created but flagged as a possible duplicate of that
442	   193	        // existing owner; otherwise the flag is false and no reference is recorded. A declared
443	   194	        // household member (created via 'sharesHousehold') is not a suspected duplicate, so it
444	   195	        // is never flagged.
445	   196	        Integer possibleDuplicateOf = (sharesHousehold && householdMember) ? null : possibleDuplicateOf(owner);
446	   197	        owner.setPossibleDuplicate(possibleDuplicateOf != null);
447	   198	        owner.setPossibleDuplicateOf(possibleDuplicateOf);
448	   199	        this.clinicService.saveOwner(owner);
449	   200	        AUDIT.info("owner created id={} customerCode={} registrationDate={} membershipLevel={} membershipNumber={}",
450	   201	            owner.getId(), owner.getCustomerCode(), owner.getRegistrationDate(),
451	   202	            ownerMapper.membershipLevel(owner), owner.getMembershipNumber());
452	   203	        OwnerDto ownerDto = ownerMapper.toOwnerDto(owner);
453	   204	        headers.setLocation(UriComponentsBuilder.newInstance()
454	   205	            .path("/api/owners/{id}").buildAndExpand(owner.getId()).toUri());
455	   206	        return new ResponseEntity<>(ownerDto, headers, HttpStatus.CREATED);
456	   207	    }
457	   208	
458	   209	    /**
459	   210	     * The owner's postal address in the single canonical form under which it is stored, or
460	   211	     * {@code null} when the owner supplies no usable address. An owner may supply its address
461	   212	     * in EITHER form: the structured {@code addressLine1} (with an optional {@code addressLine2})
462	   213	     * is preferred, and the flat {@code address} remains accepted for backward compatibility.
463	   214	     *
464	   215	     * <p>Normalization by {@link AddressNormalizer} is applied to whichever fields are supplied.
465	   216	     * When a non-blank {@code addressLine1} is present the owner's structured fields are replaced
466	   217	     * with their normalized values (a blank or absent {@code addressLine2} is cleared to
467	   218	     * {@code null}) and the returned address is composed as the normalized {@code addressLine1},
468	   219	     * with a single space and the normalized {@code addressLine2} appended when present. Otherwise
469	   220	     * the flat {@code address} is normalized and the structured fields are cleared. A blank result
470	   221	     * (no usable address in either form) has no canonical form and is reported as {@code null} so
471	   222	     * the caller can reject the request with 400.
472	   223	     *
473	   224	     * <p>This is the single point at which an owner's address is resolved and normalized on
474	   225	     * create, so every rule keyed on the stored address reads the one value produced here.
475	   226	     *
476	   227	     * @param owner the owner about to be created
477	   228	     * @return the canonical stored address, or {@code null} when the owner supplies none
478	   229	     */
479	   230	    private String normalizedAddress(Owner owner) {
480	   231	        String rawLine1 = owner.getAddressLine1();
481	   232	        if (rawLine1 != null && !rawLine1.isBlank()) {
482	   233	            String line1 = addressNormalizer.normalize(rawLine1);
483	   234	            String line2 = addressNormalizer.normalize(owner.getAddressLine2());
484	   235	            owner.setAddressLine1(line1);
485	   236	            owner.setAddressLine2(line2.isBlank() ? null : line2);
486	   237	            return line2.isBlank() ? line1 : line1 + " " + line2;
487	   238	        }
488	   239	        owner.setAddressLine1(null);
489	   240	        owner.setAddressLine2(null);
490	   241	        String address = addressNormalizer.normalize(owner.getAddress());
491	   242	        return address.isBlank() ? null : address;
492	   243	    }
493	   244	
494	   245	    /**
495	   246	     * Whether {@code candidate} collides with an already-registered owner under the single
496	   247	     * identity rule enforced on create. This is the one point at which a new owner is
497	   248	     * rejected as a duplicate (HTTP 409): all duplicate detection is consolidated into the
498	   249	     * derived {@link OwnerMapper#identityKey identityKey} — the normalized telephone, the
499	   250	     * email (or an empty string when absent) and the householdId joined by '|'. The
500	   251	     * candidate clashes only when its WHOLE identityKey equals an existing owner's; because
501	   252	     * the telephone is part of the key, two members of the same household (same householdId)
502	   253	     * with different telephones have different identityKeys and are both allowed.
503	   254	     *
504	   255	     * <p>The candidate arrives with its telephone and email already normalized and its
505	   256	     * household id already derived, and each existing owner is stored in the same canonical
506	   257	     * form, so an identityKey match means the two owners are genuinely the same identity.
507	   258	     *
508	   259	     * @param candidate the fully-normalized owner about to be created
509	   260	     * @return {@code true} if an existing owner already occupies the candidate's identityKey
510	   261	     */
511	   262	    private boolean isDuplicateOwner(Owner candidate) {
512	   263	        String identityKey = OwnerMapper.identityKey(candidate);
513	   264	        return this.clinicService.findAllOwners().stream()
514	   265	            .filter(existing -> !existing.isDeleted())
515	   266	            .map(OwnerMapper::identityKey)
516	   267	            .anyMatch(identityKey::equals);
517	   268	    }
518	   269	
519	   270	    /**
520	   271	     * The id of the existing owner the fully-normalized {@code candidate} soft-matches, or
521	   272	     * {@code null} when there is none. A soft match is an owner that is not a hard duplicate
522	   273	     * (its whole identityKey differs) yet shares the candidate's normalized last name and its
523	   274	     * postcode while carrying a different telephone — a likely re-registration of the same
524	   275	     * person under a new number. Both must supply a postcode for a match to be possible; when
525	   276	     * several existing owners qualify the lowest id is returned so the result is deterministic.
526	   277	     *
527	   278	     * @param candidate the fully-normalized owner about to be created
528	   279	     * @return the matching existing owner's id, or {@code null} if the candidate is no soft match
529	   280	     */
530	   281	    private Integer possibleDuplicateOf(Owner candidate) {
531	   282	        String postcode = candidate.getPostcode();
532	   283	        if (postcode == null) {
533	   284	            return null;
534	   285	        }
535	   286	        String lastNameKey = IdentityUtils.normalizeIdentity(candidate.getLastName());
536	   287	        return this.clinicService.findAllOwners().stream()
537	   288	            .filter(existing -> !existing.isDeleted()
538	   289	                && IdentityUtils.normalizeIdentity(existing.getLastName()).equals(lastNameKey)
539	   290	                && postcode.equals(existing.getPostcode())
540	   291	                && !postcode.isBlank()
541	   292	                && !java.util.Objects.equals(candidate.getTelephone(), existing.getTelephone()))
542	   293	            .map(Owner::getId)
543	   294	            .filter(java.util.Objects::nonNull)
544	   295	            .min(Integer::compareTo)
545	   296	            .orElse(null);
546	   297	    }
547	   298	
548	   299	    /**
549	   300	     * Build the customer code assigned to {@code owner} on create, formatted
550	   301	     * {@code '<REGION>-<HASH8>'}: REGION is the region code derived from the owner's postcode
551	   302	     * (falling back to the city) via {@link CityRegionResolver}, and HASH8 is the first eight
552	   303	     * upper-case hex characters of the SHA-256 digest of the normalized telephone concatenated
553	   304	     * with the last name (e.g. 'NSW-1A2B3C4D'). There is no per-city sequence.
554	   305	     *
555	   306	     * <p>When the computed code collides with an already-registered owner's customerCode it is
556	   307	     * de-duplicated by appending {@code '-<n>'} with the smallest {@code n} of 2 or more that
557	   308	     * makes it unique (e.g. 'NSW-1A2B3C4D-2'), and the unique code is returned.
558	   309	     */
559	   310	    private String customerCode(Owner owner) {
560	   311	        String region = cityRegionResolver.regionFor(owner.getCity(), owner.getPostcode());
561	   312	        String hash8 = HashUtils.sha256HexPrefix(owner.getTelephone() + owner.getLastName(), 8);
562	   313	        String base = region + "-" + hash8;
563	   314	        java.util.Set<String> existing = this.clinicService.findAllOwners().stream()
564	   315	            .map(Owner::getCustomerCode)
565	   316	            .filter(java.util.Objects::nonNull)
566	   317	            .collect(java.util.stream.Collectors.toSet());
567	   318	        if (!existing.contains(base)) {
568	   319	            return base;
569	   320	        }
570	   321	        int n = 2;
571	   322	        while (existing.contains(base + "-" + n)) {
572	   323	            n++;
573	   324	        }
574	   325	        return base + "-" + n;
575	   326	    }
576	   327	
577	   328	    /**
578	   329	     * The number of existing owners that share {@code owner}'s firstName and lastName,
579	   330	     * compared case-insensitively. The candidate is not yet stored at the point this is
580	   331	     * assigned, so it does not count itself. This is the value stored as the owner's
581	   332	     * namesakeCount on create.
582	   333	     */
