584	   335	        return (int) this.clinicService.findAllOwners().stream()
585	   336	            .filter(existing -> owner.getFirstName().equalsIgnoreCase(existing.getFirstName())
586	   337	                && owner.getLastName().equalsIgnoreCase(existing.getLastName()))
587	   338	            .count();
588	   339	    }
