590	   341	    /** Fixed list of public holidays that a registration date must roll past. */
591	   342	    private static final Set<LocalDate> PUBLIC_HOLIDAYS = Set.of(
592	   343	        LocalDate.of(2026, 1, 1),
593	   344	        LocalDate.of(2026, 1, 26),
594	   345	        LocalDate.of(2026, 4, 25),
595	   346	        LocalDate.of(2026, 12, 25),
596	   347	        LocalDate.of(2026, 12, 28));
