601	   352	     * that is not a public holiday. A plain weekday is returned unchanged.
602	   353	     */
603	   354	    private static LocalDate toBusinessDay(LocalDate date) {
604	   355	        while (isWeekend(date) || PUBLIC_HOLIDAYS.contains(date)) {
605	   356	            date = date.plusDays(1);
606	   357	        }
607	   358	        return date;
608	   359	    }
609	   360	
610	   361	    private static boolean isWeekend(LocalDate date) {
611	   362	        return switch (date.getDayOfWeek()) {
612	   363	            case SATURDAY, SUNDAY -> true;
613	   364	            default -> false;
614	   365	        };
615	   366	    }
616	   367	
617	   368	    /**
618	   369	     * Build the membership number assigned on create, formatted
619	   370	     * {@code '<customerCode>-M<YY>'} where YY is the last two digits of the fiscal year of the
620	   371	     * business-day-adjusted {@code registrationDate} (the fiscal year starts on 1 July), e.g.
621	   372	     * 'NSW-1A2B3C4D-M26'.
622	   373	     */
623	   374	    private static String membershipNumber(String customerCode, LocalDate registrationDate) {
624	   375	        String yy = String.format("%02d", OwnerMapper.fiscalYear(registrationDate) % 100);
625	   376	        return customerCode + "-M" + yy;
626	   377	    }
