   209	    /**
   210	     * The owner's postal address in the single canonical form under which it is stored, or
   211	     * {@code null} when the owner supplies no usable address. An owner may supply its address
   212	     * in EITHER form: the structured {@code addressLine1} (with an optional {@code addressLine2})
   213	     * is preferred, and the flat {@code address} remains accepted for backward compatibility.
   214	     *
   215	     * <p>Normalization by {@link AddressNormalizer} is applied to whichever fields are supplied.
   216	     * When a non-blank {@code addressLine1} is present the owner's structured fields are replaced
   217	     * with their normalized values (a blank or absent {@code addressLine2} is cleared to
   218	     * {@code null}) and the returned address is composed as the normalized {@code addressLine1},
   219	     * with a single space and the normalized {@code addressLine2} appended when present. Otherwise
   220	     * the flat {@code address} is normalized and the structured fields are cleared. A blank result
   221	     * (no usable address in either form) has no canonical form and is reported as {@code null} so
   222	     * the caller can reject the request with 400.
   223	     *
   224	     * <p>This is the single point at which an owner's address is resolved and normalized on
   225	     * create, so every rule keyed on the stored address reads the one value produced here.
   226	     *
   227	     * @param owner the owner about to be created
   228	     * @return the canonical stored address, or {@code null} when the owner supplies none
   229	     */
   230	    private String normalizedAddress(Owner owner) {
   231	        String rawLine1 = owner.getAddressLine1();
   232	        if (rawLine1 != null && !rawLine1.isBlank()) {
   233	            String line1 = addressNormalizer.normalize(rawLine1);
   234	            String line2 = addressNormalizer.normalize(owner.getAddressLine2());
   235	            owner.setAddressLine1(line1);
   236	            owner.setAddressLine2(line2.isBlank() ? null : line2);
   237	            return line2.isBlank() ? line1 : line1 + " " + line2;
   238	        }
   239	        owner.setAddressLine1(null);
   240	        owner.setAddressLine2(null);
   241	        String address = addressNormalizer.normalize(owner.getAddress());
   242	        return address.isBlank() ? null : address;
   243	    }
   244	
   245	    /**
   246	     * Whether {@code candidate} collides with an already-registered owner under the single
   247	     * identity rule enforced on create. This is the one point at which a new owner is
   248	     * rejected as a duplicate (HTTP 409): all duplicate detection is consolidated into the
   249	     * derived {@link OwnerMapper#identityKey identityKey} — the normalized telephone, the
   250	     * email (or an empty string when absent) and the householdId joined by '|'. The
   251	     * candidate clashes only when its WHOLE identityKey equals an existing owner's; because
   252	     * the telephone is part of the key, two members of the same household (same householdId)
   253	     * with different telephones have different identityKeys and are both allowed.
   254	     *
   255	     * <p>The candidate arrives with its telephone and email already normalized and its
   256	     * household id already derived, and each existing owner is stored in the same canonical
   257	     * form, so an identityKey match means the two owners are genuinely the same identity.
   258	     *
   259	     * @param candidate the fully-normalized owner about to be created
   260	     * @return {@code true} if an existing owner already occupies the candidate's identityKey
   261	     */
   262	    private boolean isDuplicateOwner(Owner candidate) {
   263	        String identityKey = OwnerMapper.identityKey(candidate);
   264	        return this.clinicService.findAllOwners().stream()
   265	            .filter(existing -> !existing.isDeleted())
   266	            .map(OwnerMapper::identityKey)
   267	            .anyMatch(identityKey::equals);
   268	    }
   269	
   270	    /**
   271	     * The id of the existing owner the fully-normalized {@code candidate} soft-matches, or
   272	     * {@code null} when there is none. A soft match is an owner that is not a hard duplicate
   273	     * (its whole identityKey differs) yet shares the candidate's normalized last name and its
   274	     * postcode while carrying a different telephone — a likely re-registration of the same
   275	     * person under a new number. Both must supply a postcode for a match to be possible; when
   276	     * several existing owners qualify the lowest id is returned so the result is deterministic.
   277	     *
   278	     * @param candidate the fully-normalized owner about to be created
   279	     * @return the matching existing owner's id, or {@code null} if the candidate is no soft match
   280	     */
   281	    private Integer possibleDuplicateOf(Owner candidate) {
   282	        String postcode = candidate.getPostcode();
   283	        if (postcode == null) {
   284	            return null;
   285	        }
   286	        String lastNameKey = IdentityUtils.normalizeIdentity(candidate.getLastName());
   287	        return this.clinicService.findAllOwners().stream()
   288	            .filter(existing -> !existing.isDeleted()
   289	                && IdentityUtils.normalizeIdentity(existing.getLastName()).equals(lastNameKey)
   290	                && postcode.equals(existing.getPostcode())
   291	                && !postcode.isBlank()
   292	                && !java.util.Objects.equals(candidate.getTelephone(), existing.getTelephone()))
   293	            .map(Owner::getId)
   294	            .filter(java.util.Objects::nonNull)
   295	            .min(Integer::compareTo)
   296	            .orElse(null);
   297	    }
   298	
   299	    /**
   300	     * Build the customer code assigned to {@code owner} on create, formatted
   301	     * {@code '<REGION>-<HASH8>'}: REGION is the region code derived from the owner's postcode
   302	     * (falling back to the city) via {@link CityRegionResolver}, and HASH8 is the first eight
   303	     * upper-case hex characters of the SHA-256 digest of the normalized telephone concatenated
   304	     * with the last name (e.g. 'NSW-1A2B3C4D'). There is no per-city sequence.
   305	     *
   306	     * <p>When the computed code collides with an already-registered owner's customerCode it is
   307	     * de-duplicated by appending {@code '-<n>'} with the smallest {@code n} of 2 or more that
   308	     * makes it unique (e.g. 'NSW-1A2B3C4D-2'), and the unique code is returned.
   309	     */
   310	    private String customerCode(Owner owner) {
   311	        String region = cityRegionResolver.regionFor(owner.getCity(), owner.getPostcode());
   312	        String hash8 = HashUtils.sha256HexPrefix(owner.getTelephone() + owner.getLastName(), 8);
   313	        String base = region + "-" + hash8;
   314	        java.util.Set<String> existing = this.clinicService.findAllOwners().stream()
   315	            .map(Owner::getCustomerCode)
   316	            .filter(java.util.Objects::nonNull)
   317	            .collect(java.util.stream.Collectors.toSet());
   318	        if (!existing.contains(base)) {
   319	            return base;
   320	        }
   321	        int n = 2;
   322	        while (existing.contains(base + "-" + n)) {
   323	            n++;
   324	        }
   325	        return base + "-" + n;
   326	    }
   327	
   328	    /**
   329	     * The number of existing owners that share {@code owner}'s firstName and lastName,
   330	     * compared case-insensitively. The candidate is not yet stored at the point this is
   331	     * assigned, so it does not count itself. This is the value stored as the owner's
   332	     * namesakeCount on create.
   333	     */
   334	    private int namesakeCount(Owner owner) {
   335	        return (int) this.clinicService.findAllOwners().stream()
   336	            .filter(existing -> owner.getFirstName().equalsIgnoreCase(existing.getFirstName())
   337	                && owner.getLastName().equalsIgnoreCase(existing.getLastName()))
   338	            .count();
   339	    }
   340	
   341	    /** Fixed list of public holidays that a registration date must roll past. */
   342	    private static final Set<LocalDate> PUBLIC_HOLIDAYS = Set.of(
   343	        LocalDate.of(2026, 1, 1),
   344	        LocalDate.of(2026, 1, 26),
   345	        LocalDate.of(2026, 4, 25),
   346	        LocalDate.of(2026, 12, 25),
   347	        LocalDate.of(2026, 12, 28));
   348	
   349	    /**
   350	     * Roll a registration date forward to the next business day: a Saturday, Sunday
   351	     * or listed public holiday advances one day at a time until it lands on a weekday
   352	     * that is not a public holiday. A plain weekday is returned unchanged.
   353	     */
   354	    private static LocalDate toBusinessDay(LocalDate date) {
   355	        while (isWeekend(date) || PUBLIC_HOLIDAYS.contains(date)) {
   356	            date = date.plusDays(1);
   357	        }
   358	        return date;
   359	    }
   360	
   361	    private static boolean isWeekend(LocalDate date) {
   362	        return switch (date.getDayOfWeek()) {
   363	            case SATURDAY, SUNDAY -> true;
   364	            default -> false;
   365	        };
   366	    }
   367	
   368	    /**
   369	     * Build the membership number assigned on create, formatted
   370	     * {@code '<customerCode>-M<YY>'} where YY is the last two digits of the fiscal year of the
   371	     * business-day-adjusted {@code registrationDate} (the fiscal year starts on 1 July), e.g.
   372	     * 'NSW-1A2B3C4D-M26'.
   373	     */
   374	    private static String membershipNumber(String customerCode, LocalDate registrationDate) {
   375	        String yy = String.format("%02d", OwnerMapper.fiscalYear(registrationDate) % 100);
   376	        return customerCode + "-M" + yy;
   377	    }
   378	}

